const countryName=id=>{const c=COUNTRIES.find(x=>x[0]===id);return c?L(c[1],c[2]):'';};
const placeCaption=id=>[city(id),countryName(CITY[id]?.country)].filter(Boolean).join(' · ');
const radians=x=>x*Math.PI/180;
function distanceKm(a,b){const dlat=radians(b.lat-a.lat),dlon=radians(b.lon-a.lon),x=Math.sin(dlat/2)**2+Math.cos(radians(a.lat))*Math.cos(radians(b.lat))*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
// Fictional coarse points, not actual locations of people depicted in fixture images.
Object.values(PEOPLE).forEach((p,i)=>{const c=CITY[p.city];if(c?.lat!=null)p.location={lat:Math.round((c.lat+(i%4)*.02)*20)/20,lon:Math.round((c.lon+(i%3)*.025)*20)/20};});
function nearbyDistance(id){const a=S.me.location?.coords,b=person(id)?.location;return a&&b?Math.round(distanceKm(a,b)/5)*5:null;}
const norm=x=>String(x||'').toLowerCase().replace(/ё/g,'е').replace(/[-‐–]/g,' ').trim();
const POPULAR=['moscow','spb','berlin','denpasar','tbilisi','istanbul','dubai','bangkok','almaty','belgrade','limassol','barcelona'];
/** V7: one search field for city or country; type a city that isn’t listed and add it after choosing its country */
function cityRows(){const d=S.ui.place,q=norm(d.q);
 if(d.askCountry){const cq=norm(d.cq);const list=COUNTRIES.filter(c=>!cq||norm(c[1]+' '+c[2]+' '+c[0]).includes(cq)).slice(0,60);
  return `<div class="sec" style="margin-top:4px">${L(`В какой стране «${esc(d.q.trim())}»?`,`Which country is “${esc(d.q.trim())}” in?`)}</div><div class="inwrap" style="margin-bottom:8px">${I.globe}<input class="inp" type="search" data-in="countryQuery" value="${esc(d.cq||'')}" placeholder="${L('Начни вводить страну','Start typing a country')}" aria-label="${L('Страна','Country')}"></div>${list.map(([id,ru,en])=>`<button data-act="typedCity" data-v="${id}">${I.globe}<span class="tx"><b>${esc(L(ru,en))}</b></span>${I.plus}</button>`).join('')}<button class="btn text auto mt8" data-act="placeBack">${I.back}${L('Назад к поиску','Back to search')}</button>`;}
 const all=Object.entries(CITY).filter(([id,c])=>id!=='online'&&c.country&&(!d.country||c.country===d.country));
 const hits=q?all.filter(([id,c])=>norm(c.ru+' '+c.en+' '+id).split(/\s+/).some(w=>w.startsWith(q))||norm(c.ru+' '+c.en).includes(q)):d.country?all:POPULAR.map(id=>[id,CITY[id]]).filter(([,c])=>c);
 const countries=q&&!d.country?COUNTRIES.filter(c=>norm(c[1]+' '+c[2]).split(/\s+/).some(w=>w.startsWith(q))).slice(0,3):[];
 const exact=hits.some(([,c])=>norm(c.ru)===q||norm(c.en)===q);
 return `${!q&&!d.country?`<div class="sec" style="margin-top:4px">${L('Популярные','Popular')}</div>`:''}${countries.map(([id,ru,en])=>`<button data-act="placeCountry" data-v="${id}">${I.globe}<span class="tx"><b>${esc(L(ru,en))}</b><small>${L('Показать города страны','Show cities in this country')}</small></span>${I.chev}</button>`).join('')}
 ${hits.slice(0,40).map(([id,c])=>`<button data-act="chooseCity" data-v="${esc(id)}" class="${S.ui.place.current===id?'on':''}">${I.pin}<span class="tx"><b>${esc(T(c))}</b><small>${esc(countryName(c.country))}</small></span>${S.ui.place.current===id?I.check:''}</button>`).join('')}
 ${q.length>=2&&!exact?`<button data-act="typedCityStart" class="add">${I.plus}<span class="tx"><b>${L(`Добавить «${esc(d.q.trim())}»`,`Add “${esc(d.q.trim())}”`)}</b><small>${d.country?esc(countryName(d.country)):L('Нет в списке — укажем вручную','Not listed — add it manually')}</small></span></button>`:''}
 ${q&&!hits.length&&!countries.length&&q.length<2?``:''}`;
}
function openCityPicker(current,done,o={}){S.ui.place={country:'',q:'',current,done,clear:o.clear,owner:S,route:cur()};sheet(()=>{const d=S.ui.place;return{title:L('Город','City'),body:`<div class="inwrap place-q">${I.search}<input type="search" class="inp" id="placeQ" data-in="placeQuery" value="${esc(d.q)}" placeholder="${L('Город или страна','City or country')}" aria-label="${L('Поиск города или страны','Search city or country')}" autocomplete="off" enterkeyhint="search" autofocus></div>${d.country?`<div class="chips" style="margin:10px 0 2px"><button class="chip on" data-act="placeCountry" data-v="">${I.globe}${esc(countryName(d.country))} ${ic('close',14)}</button></div>`:''}${d.clear&&d.current&&!d.q?`<button class="li" data-act="placeClear"><span class="ico">${I.eyeoff}</span><span class="tx"><b>${L('Не показывать город','Don’t show city')}</b></span></button>`:''}<div class="location-results" id="placeResults">${cityRows()}</div>`};},{full:true});}
IN.placeQuery=el=>{S.ui.place.q=el.value;S.ui.place.askCountry=false;$('#placeResults').innerHTML=cityRows();};
IN.countryQuery=el=>{S.ui.place.cq=el.value;const pos=el.selectionStart;$('#placeResults').innerHTML=cityRows();const n=$('[data-in="countryQuery"]');n.focus();n.setSelectionRange(pos,pos);};
ACT.placeCountry=a=>{const d=S.ui.place;d.country=a.dataset.v;if(a.dataset.v)d.q='';resheet();$('#placeQ')?.focus();};
ACT.placeBack=()=>{S.ui.place.askCountry=false;$('#placeResults').innerHTML=cityRows();};
function finishCity(id){const d=S.ui.place;if(S!==d.owner||cur()!==d.route)return;closeSheet();d.done(id);}
ACT.chooseCity=a=>finishCity(a.dataset.v);
ACT.typedCityStart=()=>{const d=S.ui.place;if(d.country)return ACT.typedCity({dataset:{v:d.country}});d.askCountry=true;d.cq='';$('#placeResults').innerHTML=cityRows();};
ACT.typedCity=a=>{const d=S.ui.place;const c=a.dataset.v;const name=d.q.trim();if(!c||name.length<2)return;const nm=name[0].toUpperCase()+name.slice(1);const id='city-'+c+'-'+norm(nm).replace(/\s+/g,'-');CITY[id]=CITY[id]||{ru:nm,en:nm,country:c,custom:true};finishCity(id);toast(L(`Добавили «${nm}». Проверим написание — людям рядом город покажется так же`,`Added “${nm}”. We’ll check the spelling so people nearby see it the same way`),{type:'ok'});};
function requestCoarseLocation(done){
 if(!navigator.geolocation){toast(L('Расположение недоступно. Выбери город вручную.','Location is unavailable. Choose a city manually.'),{type:'warn'});return;}
 const owner=S,route=cur();toast(L('Запрашиваем примерное расположение','Requesting approximate location'),{type:'info'});
 navigator.geolocation.getCurrentPosition(pos=>{if(S!==owner||cur()!==route)return;const coords={lat:Math.round(pos.coords.latitude*20)/20,lon:Math.round(pos.coords.longitude*20)/20};done(coords);},()=>{if(S===owner&&cur()===route)toast(L('Расположение не получено. Можно искать по городу.','Location was not available. You can search by city.'),{type:'warn'});},{enableHighAccuracy:false,timeout:12000,maximumAge:300000});
}
function locationFields(f,cityAct,modeAct,geoAct){const mode=f.placeMode||'city';return `<div class="sec">${L('Где искать','Where to search')}</div>${choices([['city',L('По городу','By city')],['nearby',L('Рядом','Nearby')]],mode,modeAct)}<button class="li" data-act="${cityAct}"><span class="ico">${I.pin}</span><span class="tx"><b>${f.city?esc(placeCaption(f.city)):L('Выбрать страну и город','Choose country and city')}</b><small>${L('Поиск по названию города','Search by city name')}</small></span>${I.chev}</button>${mode==='nearby'?`<p class="note mt8">${L('Только примерная область около 5 км. Точная точка и адрес не сохраняются и не показываются.','Only a coarse area of about 5 km. Your exact position and address are never stored or displayed.')}</p><button class="btn soft mt8" data-act="${geoAct}">${I.pin}${f.coords?L('Обновить примерное расположение','Update approximate location'):L('Указать примерное расположение','Set approximate location')}</button>${f.coords?`<p class="note mt8">${L('Примерная область выбрана','Approximate area is set')}</p>`:''}`:''}`;}

function nearestKnownCity(coords){const near=PLACES.map(([id,country,ru,en,lat,lon])=>({id,km:distanceKm(coords,{lat,lon})})).sort((a,b)=>a.km-b.km)[0];return near?.km<=50?near.id:'';}

ACT.placeClear=()=>{const d=S.ui.place;if(!d)return;closeSheet();d.done('');};
